// SetCursor set the tablet tool's surface.
//
// Sets the surface of the cursor used for this tool on the given
// tablet. This request only takes effect if the tool is in proximity
// of one of the requesting client's surfaces or the surface parameter
// is the current pointer surface. If there was a previous surface set
// with this request it is replaced. If surface is NULL, the cursor
// image is hidden.
//
// The parameters hotspot_x and hotspot_y define the position of the
// pointer surface relative to the pointer location. Its top-left corner
// is always at (x, y) - (hotspot_x, hotspot_y), where (x, y) are the
// coordinates of the pointer location, in surface-local coordinates.
//
// On surface.attach requests to the pointer surface, hotspot_x and
// hotspot_y are decremented by the x and y parameters passed to the
// request. Attach must be confirmed by wl_surface.commit as usual.
//
// The hotspot can also be updated by passing the currently set pointer
// surface to this request with new values for hotspot_x and hotspot_y.
//
// The current and pending input regions of the wl_surface are cleared,
// and wl_surface.set_input_region is ignored until the wl_surface is no
// longer used as the cursor. When the use as a cursor ends, the current
// and pending input regions become undefined, and the wl_surface is
// unmapped.
//
// This request gives the surface the role of a wp_tablet_tool cursor. A
// surface may only ever be used as the cursor surface for one
// wp_tablet_tool. If the surface already has another role or has
// previously been used as cursor surface for a different tool, a
// protocol error is raised.
func (o *TabletToolV2) SetCursor(serial uint32, surface wire.ObjectID, hotspotX int32, hotspotY int32) error {
	return o.proxy.SendRequest(TabletToolV2RequestSetCursor, &TabletToolV2SetCursorRequest{
		Serial:   serial,
		Surface:  surface,
		HotspotX: hotspotX,
		HotspotY: hotspotY,
	})
}

// Destroy destroy the tool object.
//
// This destroys the client's resource for this tool object.
func (o *TabletToolV2) Destroy() error {
	if o.proxy.Deleted() {
		return nil
	}
	if err := o.proxy.SendRequest(TabletToolV2RequestDestroy, &TabletToolV2DestroyRequest{}); err != nil {
		return err
	}
	o.proxy.Conn().UnregisterProxy(o.proxy.ID())
	return nil
}

// BindTabletToolV2 binds the zwp_tablet_tool_v2 global advertised by the server.
// version is the version requested by the application; it must be within
// [1, VersionTabletToolV2] or ErrVersionMismatch is returned. Servers newer
// than this library may advertise a higher version: clamp the advertised
// version with the builtin min, e.g. BindTabletToolV2(reg, name, min(g.Version,
// VersionTabletToolV2)), to bind at the highest mutually supported version.
func BindTabletToolV2(b wayland.Binder, name uint32, version uint32) (*TabletToolV2, error) {
	if version < 1 || version > VersionTabletToolV2 {
		return nil, wayland.ErrVersionMismatch
	}
	p, err := b.Bind(name, InterfaceTabletToolV2, version)
	if err != nil {
		return nil, err
	}
	x := NewTabletToolV2(p)
	x.proxy.SetVersion(version)
	return x, nil
}
